function smallestOutput(s: string): string {
  const stack: string[] = [];
  let out = "";
  for (let i = 0; i < s.length; i++) {
    stack.push(s[i]);
    let restMin = "{";
    for (let j = i + 1; j < s.length; j++) if (s[j] < restMin) restMin = s[j];
    while (stack.length && stack[stack.length - 1] <= restMin) out += stack.pop();
  }
  return out;
}

