function smallestOutput(s: string): string {
  const n = s.length;
  const sufMin: string[] = new Array(n + 1);
  sufMin[n] = "{"; // "{" sorts after "z"
  for (let i = n - 1; i >= 0; i--) sufMin[i] = s[i] < sufMin[i + 1] ? s[i] : sufMin[i + 1];
  const stack: string[] = [], out: string[] = [];
  for (let i = 0; i < n; i++) {
    stack.push(s[i]);
    while (stack.length && stack[stack.length - 1] <= sufMin[i + 1]) out.push(stack.pop()!);
  }
  return out.join("");
}

