class Solution:
    def smallestOutput(self, s: str) -> str:
        n = len(s)
        suf_min = ["{"] * (n + 1)  # "{" sorts after "z"
        for i in range(n - 1, -1, -1):
            suf_min[i] = min(s[i], suf_min[i + 1])
        stack, out = [], []
        for i, ch in enumerate(s):
            stack.append(ch)
            while stack and stack[-1] <= suf_min[i + 1]:
                out.append(stack.pop())
        return "".join(out)

